# Create a set of liked song IDs for quick lookup
liked_ids = {s['song_id'] for s in liked_songs}
print("Liked IDs set:", liked_ids)

# Check if current song is already liked
if current_song['song_id'] in liked_ids:
    print("Current song is already liked:", current_song['title'])
else:
    # Keep going to next song until we find a liked one
    max_steps = 100  # safety limit
    for i in range(max_steps):
        next_result = apis.spotify.next_song(access_token=access_token)
        print(f"Step {i+1}: next_song returned song_id={next_result.get('song_id')}")
        # Get the new current song details
        new_current = apis.spotify.show_current_song(access_token=access_token)
        print(f"  Now playing: {new_current['title']} (id={new_current['song_id']})")
        if new_current['song_id'] in liked_ids:
            print("Found a liked song!")
            break
    else:
        print("No liked song found after max steps")

