steps.code:
# Verify no other playlist still contains any of the old songs
old_song_ids = set([74, 280, 261, 311, 29, 43, 162, 128, 207, 308, 257, 172, 131, 127])
remaining_pairs = []
for pl in all_playlists:
    pl_id = pl['playlist_id']
    pl_info = apis.spotify.show_playlist(playlist_id=pl_id, access_token=spotify_token)
    for song in pl_info['songs']:
        if song['id'] in old_song_ids:
            remaining_pairs.append((pl_id, song['id']))
print("Remaining old songs in playlists:", remaining_pairs)

# Fetch all playlists and verify the final state
all_playlists = []
page_index = 0
page_limit = 20
while True:
    response = apis.spotify.show_playlist_library(access_token=spotify_token, page_index=page_index, page_limit=page_limit)
    if not response:
        break
    all_playlists.extend(response)
    if len(response) < page_limit:
        break
    page_index += 1

# The set of old song IDs that should be in the archived playlist
old_song_ids = {29, 43, 74, 127, 128, 131, 162, 172, 207, 257, 261, 280, 308, 311}

archived_playlist = None
violations = []
for pl in all_playlists:
    pl_id = pl['playlist_id']
    pl_title = pl['title']
    pl_song_ids = set(pl.get('song_ids', []))
    if pl_title == 'Archived Songs':
        archived_playlist = pl
        if pl_song_ids != old_song_ids:
            print(f"Archived playlist mismatch: {pl_song_ids}")
    else:
        # Check if any old song remains in other playlists
        overlap = pl_song_ids & old_song_ids
        if overlap:
            violations.append((pl_title, sorted(overlap)))

if archived_playlist is None:
    print("Archived playlist not found!")
else:
    print("Archived playlist found with correct songs:", sorted(archived_playlist['song_ids']))

if violations:
    print("Violations (old songs still in other playlists):", violations)
else:
    print("All old songs removed from all other playlists.")

