# Let's search for all songs in songs_to_archive and collect their song_ids
# We'll match by title and artist name
song_ids_to_archive = []
for song in songs_to_archive:
    results = apis.spotify.search_songs(query=song['title'], access_token=spotify_token, page_index=0, page_limit=20)
    # Find the exact match
    found = False
    for result in results:
        if result['title'] == song['title']:
            # Check if any artist matches
            for artist in result['artists']:
                if artist['name'] == song['artist']:
                    song_ids_to_archive.append(result['song_id'])
                    found = True
                    break
            if found:
                break
    if not found:
        print(f"Could not find song: {song['title']} by {song['artist']}")

print("Song IDs to archive:", song_ids_to_archive)
print("Count:", len(song_ids_to_archive))

