# Let's update the note content by replacing all "TODO" with the release month from song_release_dates.
# We'll parse each line, extract the song title, look up the release month, and replace "TODO".

lines = note_content.split('\n')
new_lines = []
for line in lines:
    if 'RELEASED_AT TODO' in line:
        # Extract song title: line starts with "- " and then title before " BY "
        # Example: "- Silver Lining BY Ava Morgan RELEASED_AT TODO"
        # Find " BY " to get title
        if ' BY ' in line:
            title_part = line.split(' BY ')[0].strip()
            # Remove leading "- " if present
            if title_part.startswith('- '):
                title = title_part[2:].strip()
            else:
                title = title_part.strip()
            if title in song_release_dates:
                release_month = song_release_dates[title]
                # Replace "TODO" with release_month
                new_line = line.replace('RELEASED_AT TODO', f'RELEASED_AT {release_month}')
                new_lines.append(new_line)
            else:
                # If not found, keep as is (shouldn't happen)
                new_lines.append(line)
        else:
            new_lines.append(line)
    else:
        new_lines.append(line)

new_content = '\n'.join(new_lines)
print(new_content)

